import { Micro, Milli } from "@moq/clock";
import * as Catalog from "@moq/hang/catalog";
import * as Container from "@moq/hang/container";
import * as Moq from "@moq/net";
import { Signal } from "@moq/signals";
import type { Broadcast } from "../../../../../js/watch/src/broadcast";
import { Sync } from "../../../../../js/watch/src/sync";
import { Decoder } from "../../../../../js/watch/src/video/decoder";
import { Source } from "../../../../../js/watch/src/video/source";

/** One real open-GOP access unit generated by ffmpeg. */
export type Packet = { group: number; timestamp: number; data: string };

declare global {
	interface Window {
		runRecovery(packets: Packet[]): Promise<{ submitted: number[]; decoded: number; software: boolean }>;
	}
}

window.runRecovery = async (packets) => {
	const Native = window.VideoDecoder;
	const codecs: VideoDecoder[] = [];
	const submitted: number[] = [];
	let decoded = 0;
	let software = true;
	let failed: Error | undefined;
	let ended!: () => void;
	const inputDone = new Promise<void>((resolve) => {
		ended = resolve;
	});
	const next = Container.Consumer.prototype.next;
	Container.Consumer.prototype.next = async function () {
		const item = await next.call(this);
		if (!item) ended();
		return item;
	};
	window.VideoDecoder = class extends Native {
		constructor(init: VideoDecoderInit) {
			super({
				output(frame) {
					decoded++;
					init.output(frame);
				},
				error(error) {
					failed = error;
					ended();
					init.error(error);
				},
			});
			codecs.push(this);
		}
		override configure(config: VideoDecoderConfig) {
			const softwareConfig = { ...config, hardwareAcceleration: "prefer-software" as const };
			software &&= softwareConfig.hardwareAcceleration === "prefer-software";
			super.configure(softwareConfig);
		}
		override decode(chunk: EncodedVideoChunk) {
			submitted.push(chunk.timestamp);
			super.decode(chunk);
		}
	};
	const producer = new Moq.Broadcast.Producer();
	const track = producer.createTrack("video", { timescale: Moq.Time.Timescale.MICRO });
	let group: Moq.Group.Producer | undefined;
	for (const packet of packets) {
		if (group?.sequence !== packet.group) {
			group?.close();
			group = new Moq.Group.Producer(packet.group);
			track.writeGroup(group);
		}
		const timestamp = Micro(packet.timestamp);
		const payload = Uint8Array.from(atob(packet.data), (c) => c.charCodeAt(0));
		group.writeFrame({
			payload: Container.Legacy.encodeFrame(payload, timestamp),
			timestamp: Moq.Time.Timestamp.fromMicros(timestamp),
		});
	}
	group?.close();
	track.close();
	const media = producer.consume();
	const config = Catalog.VideoConfigSchema.parse({
		codec: "avc1.64001f",
		container: { kind: "legacy" },
		codedWidth: 160,
		codedHeight: 96,
	});
	const catalog = new Signal<Catalog.Root>({ video: { renditions: { video: config } } });
	const broadcast = new Signal<Broadcast | undefined>({
		out: { catalog, active: new Signal(media) },
		relativeBroadcast: () => media,
	} as unknown as Broadcast);
	const source = new Source({ broadcast, supported: async () => true });
	const sync = new Sync({ delay: Milli(0), buffer: Milli(10_000) });
	const decoder = new Decoder({ source, sync });
	try {
		await inputDone;
		if (failed) throw failed;
		for (const codec of codecs) await codec.flush();
		if (failed) throw failed;
		return { submitted, decoded, software };
	} finally {
		decoder.close();
		source.close();
		sync.close();
		media.close();
		producer.close();
		window.VideoDecoder = Native;
		Container.Consumer.prototype.next = next;
	}
};
